mapper.select:
select proxy.id,proxy.PARK_ID,park.PARK_NAME,proxy.INTERVIEWEE_BADGE AS interVieweeBadge, istaff.NAME AS interVieweeName,istaff.COMP_ID AS interVieweeCompId,istaff.COMP_NAME AS interVieweeCompName, istaff.DEP_ID AS interVieweeDepId,istaff.DEP_NAME AS interVieweeDepName,istaff.JOB_ID AS interVieweeJobId,istaff.JOB_NAME AS interVieweeJobName, proxy.PROXY_BADGE as proxyBadge, pstaff.NAME AS proxyName,pstaff.COMP_ID AS proxyCompId,pstaff.COMP_NAME AS proxyCompName, pstaff.DEP_ID AS proxyDepId,pstaff.DEP_NAME AS proxyDepName,pstaff.JOB_ID AS proxyJobId,pstaff.JOB_NAME AS proxyJobName, proxy.CREATE_TIME from SMT_VISITOR_APPROVAL_PROXY proxy join SMT_STAFF pstaff on proxy.PROXY_BADGE=pstaff.BADGE join SMT_STAFF istaff on proxy.INTERVIEWEE_BADGE=istaff.BADGE join SMT_PARK park on proxy.PARK_ID=park.ID
and proxy.PARK_ID=#{query.parkId}
and proxy.PARK_ID in
#{item}
and proxy.PROXY_BADGE=#{query.proxyBadge}
AND proxy.INTERVIEWEE_BADGE=#{query.interVieweeBadge}
AND pstaff.name LIKE CONCAT(CONCAT('%',#{query.proxyName}),'%')
AND istaff.name LIKE CONCAT(CONCAT('%',#{query.interVieweeName}),'%')
